// Generated by scripts/import_learning_v2_first_ten_candidate.mjs.
import { EPISODE_01_SESSION_05_SOURCE } from '../modules/learning-v2/content/source/episode_01_session_05_v1';
import { assertApprovedFirstTenSession } from './learning_v2_approved_first_ten_source_assertions';
import fs from 'node:fs';
import path from 'node:path';

const sessionRoot = path.resolve(__dirname, '../content/learning-v2-course/sessions/en/l01/s05');
const readSource = (name: string) => fs.readFileSync(path.join(sessionRoot, name), 'utf8');

describe('episode 1 approved session 5 source', () => {
  test('matches the authored S05 projection and runtime contract', () => {
    assertApprovedFirstTenSession(
      EPISODE_01_SESSION_05_SOURCE,
      5,
      '2c205df606f5df6cfc1ad946fe7677dafa29ce6a1f8894b6351e7d429cfd9139',
      7,
      60,
      false,
      3,
    );
  });

  test('keeps Russian and Ukrainian wording scoped, accurate, and natural', () => {
    const ru = readSource('final.ru.md');
    const uk = readSource('final.uk.md');

    expect(ru).toContain('Марина спрашивает возле чайника');
    expect(uk).toContain('Марина питає біля чайника');
    expect(ru).toContain('В нейтральной фразе о себе отрицание строится так');
    expect(uk).toContain('У нейтральному реченні про себе заперечення будується так');
    expect(ru).toContain('Значение `lost` зависит от контекста');
    expect(uk).toContain('Значення `lost` залежить від контексту');
    expect(ru).not.toMatch(/no.{0,60}(?:только|лишь).{0,40}одним словом/iu);
    expect(uk).not.toMatch(/no.{0,60}(?:тільки|лише).{0,40}одним словом/iu);
    expect(uk).toContain('Сьогодні ваш перший день у компанії');
    expect(ru).toContain('I am not new. — я здесь не впервые');
    expect(uk).toContain('I am not new. — я тут не вперше');
  });

  test('has exactly twenty practice tasks in both learner locales', () => {
    for (const locale of ['ru', 'uk']) {
      const source = readSource(`final.${locale}.md`);
      const numberedTasks = source.match(/^\*\*\d+ ·/gmu) ?? [];
      expect(numberedTasks).toHaveLength(20);
      expect(source).toContain(locale === 'ru' ? 'Практика (20 заданий' : 'Практика (20 завдань');
    }
  });

  test('keeps S05 feedback wrong-answer-only while retaining specific wrong-answer help', () => {
    const practice = JSON.parse(readSource('practice.atomic.json')) as {
      interactionsByLocale: Record<string, Array<{ interactionId: string; modePayload?: { choiceFeedback?: Array<{ correct: boolean; testedDimension?: string; feedbackByLocale: Record<string, string> }> } }>>
    };
    const expectedIds = ['i02', 'i06', 'i08', 'i10', 'i12', 'i15'];

    for (const locale of ['ru', 'uk']) {
      const interactions = practice.interactionsByLocale[locale];
      expect(interactions).toHaveLength(20);
      for (const suffix of expectedIds) {
        const interaction = interactions.find(({ interactionId }) => interactionId.endsWith(suffix));
        expect(interaction).toBeDefined();
        const feedback = interaction?.modePayload?.choiceFeedback ?? [];
        expect(feedback.some(({ correct }) => correct)).toBe(false);
        expect(feedback.filter(({ correct }) => !correct)).toHaveLength(2);
        expect(feedback.filter(({ correct }) => !correct).every(({ testedDimension, feedbackByLocale }) => Boolean(testedDimension && feedbackByLocale.ru && feedbackByLocale.uk))).toBe(true);
      }
    }
  });

  test('keeps locales_batch as an exact wrapper of the current Ukrainian learner source', () => {
    const batch = readSource('locales_batch.md');
    expect(batch).toBe(`===LOCALE: uk===\n${readSource('final.uk.md').trim()}\n`);
  });
});
